package vn.vinhkhang.warehouse;
import java.util.*;import java.io.*;import java.nio.file.*;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.NONE,properties={"spring.datasource.url=jdbc:h2:mem:excel_import;DB_CLOSE_DELAY=-1"})
class ExcelImportsTest {
 @Autowired Api core;@Autowired FirstSetup setup;@Autowired ExcelImports imports;@Autowired JdbcTemplate db;
 String file(String kind,String[][] rows,String output)throws Exception {try(var wb=new XSSFWorkbook(Files.newInputStream(Path.of("../public/templates/"+kind+".xlsx")));var out=new ByteArrayOutputStream()){var sheet=wb.getSheet(kind.equals("parts")?"Linh kien":"BOM");for(int r=0;r<rows.length;r++){var row=sheet.createRow(r+1);for(int c=0;c<rows[r].length;c++)row.createCell(c).setCellValue(rows[r][c]);}wb.write(out);if(output!=null){Path path=Path.of("../work/excel013-fixtures/"+output+".xlsx");Files.createDirectories(path.getParent());Files.write(path,out.toByteArray());}return Base64.getEncoder().encodeToString(out.toByteArray());}}
 @SuppressWarnings("unchecked") Map<String,Object> preview(String token,String kind,String file){return (Map<String,Object>)imports.preview(token,kind,Map.of("file",file));}
 Object commit(String token,String kind,String file,Map<String,Object> p){return imports.commit(token,kind,Map.of("file",file,"fingerprint",p.get("fingerprint"),"confirmation","NHAP EXCEL"));}
 @Test @SuppressWarnings("unchecked") void importsAreAtomicVersionedAndNeverTouchStock()throws Exception{
  setup.create(Map.of("username","factory","display_name","Nhà máy","password","a","confirm_password","a","account_kind","FACTORY"));String t=core.login(new Api.Login("factory","a")).get("token").toString();long a=core.create("models",t,Map.of("code","S800","name","S800")).get("id"),b=core.create("models",t,Map.of("code","S650","name","S650")).get("id");long old=core.create("parts",t,Map.of("code","LK1","name","Lốp","unit","Cái")).get("id");long oldBom=core.bom(t,Map.of("model_id",a,"version",1,"lines",List.of(Map.of("part_id",old,"quantity",1)))).get("id");
  String f=file("parts",new String[][]{{"","Tem nhựa thử","Bộ","S800;S650"},{"LK9","Càng thử","Cái",""}},"parts-valid");var p=preview(t,"parts",f);assertEquals(true,p.get("valid"));assertEquals("LK2",((List<Map<String,Object>>)p.get("rows")).getFirst().get("code"));assertEquals(1,core.list("parts",t).size());commit(t,"parts",f,p);assertEquals(3,core.list("parts",t).size());assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM part_color_models",Integer.class));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM stock_balances",Integer.class));assertEquals(false,preview(t,"parts",f).get("valid"));
  String bad=file("parts",new String[][]{{"LK20","Hợp lệ","Cái",""},{"LK1","Lỗi trùng","Cái",""}},"parts-invalid");var invalid=preview(t,"parts",bad);assertEquals(false,invalid.get("valid"));assertThrows(Api.Problem.class,()->commit(t,"parts",bad,invalid));assertEquals(3,core.list("parts",t).size());
  String stale=file("parts",new String[][]{{"","Phần thêm","Cái",""}},null);var snapshot=preview(t,"parts",stale);core.create("parts",t,Map.of("code","LK50","name","Đổi danh mục","unit","Cái"));assertThrows(Api.Problem.class,()->commit(t,"parts",stale,snapshot));
  String bf=file("bom",new String[][]{{"S800","LK1","Lốp","2"},{"S800","LK2","Tem nhựa thử","1"},{"S650","LK2","","1"}},"bom-valid");var bp=preview(t,"bom",bf);assertEquals(true,bp.get("valid"));assertEquals(2L,((List<Map<String,Object>>)bp.get("rows")).getFirst().get("version"));commit(t,"bom",bf,bp);assertEquals(3,core.list("bom",t).size());assertEquals("1.000",db.queryForObject("SELECT quantity FROM bom_lines WHERE bom_id=?",java.math.BigDecimal.class,oldBom).toPlainString());assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM vehicles",Integer.class));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM stock_movements",Integer.class));
  String bbad=file("bom",new String[][]{{"S800","LK1","Sai tên","1"},{"S650","LK1","","0"},{"S800","NOT_FOUND","","1"}},"bom-invalid");assertEquals(false,preview(t,"bom",bbad).get("valid"));assertEquals(3,((List<?>)preview(t,"bom",bbad).get("errors")).size());
  core.create("users",t,Map.of("username","viewer","display_name","Xem","password","a","role","VIEWER","account_kind","FACTORY"));String view=core.login(new Api.Login("viewer","a")).get("token").toString();assertThrows(Api.Problem.class,()->preview(view,"parts",f));core.create("users",t,Map.of("username","store","display_name","Cửa hàng","password","a","role","ADMIN","account_kind","STORE"));String st=core.login(new Api.Login("store","a")).get("token").toString();assertThrows(Api.Problem.class,()->preview(st,"bom",bf));
  try(var wb=new XSSFWorkbook(Files.newInputStream(Path.of("../public/templates/parts.xlsx")));var out=new ByteArrayOutputStream()){var row=wb.getSheet("Linh kien").createRow(1);row.createCell(0).setCellFormula("1+1");wb.write(out);assertEquals(false,preview(t,"parts",Base64.getEncoder().encodeToString(out.toByteArray())).get("valid"));}
 }
}
